export class MockProvider implements DashboardDataProvider {
  readonly kind = 'mock' as const;

  async load() {
    const normalized = normalizeSheetRows(MOCK_TODAY_ROWS, MOCK_RESEARCH_ROWS);

    const meta: Omit<DataSourceMeta, 'cacheAgeMs' | 'stale'> = {
      provider: this.kind,
      fetchedAt: new Date().toISOString(),
      sourceUpdatedAt: null,
      error: null,
      sourceTitle: 'Mock dataset (no Google credentials configured)',
      warnings: normalized.warnings,
    };

    return {
      tickers: normalized.tickers,
      research: normalized.research,
      summary: normalized.summary,
      meta,
    };
  }
}
